var o=[{title:`Prepare cada posto`,text:`Verifique o banco, o rack, a máquina ou o acessório antes de o carregar. Regule corretamente os assentos e as barras de segurança, use fechos quando necessário e certifique-se de que os discos estão presos nos dois lados. Mantenha sacos e acessórios soltos fora dos corredores. Se não souber como funciona uma máquina, peça ao pessoal que lhe mostre.`},{title:`Partilhe o espaço`,text:`Volte a pôr os halteres e os discos no lugar, limpe o equipamento como o ginásio pede e devolva os acessórios das polias. Não ocupe várias máquinas ao mesmo tempo nas horas de ponta. Pergunte com delicadeza se pode alternar e combine como mudar o peso ou o assento em segurança antes de partilhar um posto.`},{title:`Ajudantes e seguranças`,text:`Nos supinos ou agachamentos difíceis, regule os braços de segurança sempre que puder e use um ajudante que saiba o que está a fazer quando precisar de um. Não conte que um desconhecido por perto repare numa repetição falhada. Pratique montar um rack com cargas leves antes de levantar pesado e nunca entre no trajeto de levantamento de outra pessoa.`},{title:`Períodos de maior afluência`,text:`Tenha uma alternativa para o equipamento mais procurado: uma remada com haltere pode substituir uma remada na polia, e um agachamento goblet pode substituir um agachamento no rack se a carga ainda lhe servir. O seu treino não depende de conseguir um posto em particular. Uma montagem apressada ou com muita gente continua a não ser razão para facilitar na técnica ou saltar o aquecimento.`}];var s=[{label:`Mayo Clinic: segurança e técnica no treino com pesos`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};